describe('Login Form Validation - Empty Fields', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should prevent form submission when email and password fields are empty', () => {
    // Verify login form is visible
    cy.get('[data-testid="login-form"]').should('be.visible');
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="password-input"]').should('be.visible');
    cy.get('[data-testid="login-button"]').should('be.visible');

    // Attempt to submit the form without entering any data
    cy.get('[data-testid="login-button"]').click();

    // Verify error messages appear for both fields
    cy.get('[data-testid="email-error"]').should('be.visible').should('contain', 'Email is required');
    cy.get('[data-testid="password-error"]').should('be.visible').should('contain', 'Password is required');

    // Verify form was not submitted (no redirect or API call)
    cy.url().should('include', '/login');
    cy.get('[data-testid="login-form"]').should('be.visible');
  });

  it('should prevent form submission when only email field is filled and password is empty', () => {
    // Fill only the email field
    cy.get('[data-testid="email-input"]').type('user@example.com');

    // Attempt to submit the form
    cy.get('[data-testid="login-button"]').click();

    // Verify password error message appears
    cy.get('[data-testid="password-error"]').should('be.visible').should('contain', 'Password is required');

    // Verify email error does not appear (or is cleared)
    cy.get('[data-testid="email-error"]').should('not.exist');

    // Verify form was not submitted
    cy.url().should('include', '/login');
    cy.get('[data-testid="login-form"]').should('be.visible');
  });
});
